// Link actual game hooks to the verbatim production tone queue/PCM renderer.
#include "../runtime.hpp"
#include <algorithm>
#include <cassert>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
#ifdef APP_CRISP_ARCADE
#include "../../../crisp-arcade/core_bridge.h"
#include "../../../crisp-arcade/vendor/src/lib/sound.h"
#endif
namespace {
uint32_t clock_ms=0;bool background=false,paused=false,exit_requested=false;
uint64_t foreground_us(){return uint64_t(clock_ms)*1000;}
void pxa_audio_flush(uint64_t,uint64_t){}
// Generated by run-sfx-pcm.py from audio.inc, without changing production code.
#include "audio-render-prefix.inc"
unsigned tone_calls=0;uint16_t pixels[pocket::WIDTH*pocket::HEIGHT]{};
std::vector<int16_t> capture;
void step(unsigned ms){
    assert(ms%20==0);
    for(unsigned i=0;i<ms;i+=20){
        game::tick(20);render_sound();capture.insert(capture.end(),sound_pcm,sound_pcm+SOUND_BLOCK);
        sound_cursor+=SOUND_BLOCK;clock_ms+=20;
#ifdef APP_CRISP_ARCADE
        assert(!isPlayingBgm);
#endif
    }
}
void tap(int x,int y){game::pointer(pocket::Phase::DOWN,x,y);game::pointer(pocket::Phase::UP,x,y);}
size_t nonzero(){return std::count_if(capture.begin(),capture.end(),[](int16_t p){return p!=0;});}
void store(const std::string &path){FILE *f=std::fopen(path.c_str(),"wb");assert(f);assert(std::fwrite(capture.data(),sizeof(int16_t),capture.size(),f)==capture.size());std::fclose(f);}
}
namespace pocket {
void pixel(int,int,uint16_t){}void rect(int,int,int,int,uint16_t){}void clear(uint16_t){}void outline(int,int,int,int,uint16_t){}void line(int,int,int,int,uint16_t){}
void text(int,int,const char*,uint16_t,int){}int text_width(const char *s,int scale){return pocket_ui::text_width(s,scale);}
void redraw(){}void save(){}uint32_t random(){return 0x12345678;}uint32_t millis(){return clock_ms;}void log(const char *s){std::puts(s);}bool held(Key){return false;}uint16_t *framebuffer(){return pixels;}
void tone(float f,float d,float w){++tone_calls;add_tone(f,d,w);}void silence(){clear_sound();}
}
#ifdef APP_LANTERN_GROVE
namespace grove {uint64_t monotonic_ms(){return 100000+clock_ms;}uint64_t wall_seconds(){return 1792771200+clock_ms/1000;}}
#endif
int main(int argc,char **argv){
    assert(argc==2);const std::string out=argv[1];game::init();step(3000);
    const size_t idle=nonzero();assert(idle==0);assert(tone_calls==0);store(out+"/idle.s16");capture.clear();
#ifdef APP_PET_GARDEN
    tap(24,191);
#elif defined(APP_LANTERN_GROVE)
    tap(50,183);
#elif defined(APP_HARBOR_CAFE)
    tap(143,179);
#elif defined(APP_TINY_ELEMENTS)
    tap(100,195);step(300);game::key(pocket::Key::R);
#elif defined(APP_MARBLE_ISLANDS)
    tap(140,120);tap(40,204);tap(210,65);
#elif defined(APP_CRISP_ARCADE)
    tap(200,140);step(200);for(unsigned i=0;i<8;++i){tap(140,120);step(160);}
#endif
    step(1000);const size_t event=nonzero();assert(event>0&&tone_calls>0);store(out+"/event.s16");capture.clear();
#ifdef APP_CRISP_ARCADE
    // Every selected game and runtime restart must leave generated BGM disabled.
    for(int i=0;i<4;++i){game::key(pocket::Key::B);tap(20+(i%2)*140,50+(i/2)*75);step(200);game::reset();step(200);assert(!isPlayingBgm);}
    game::key(pocket::Key::B);
#elif defined(APP_MARBLE_ISLANDS)
    game::key(pocket::Key::B);
#endif
    step(2000);capture.clear();const unsigned settled=tone_calls;step(3000);const size_t after=nonzero();assert(after==0&&tone_calls==settled);store(out+"/settled.s16");
    std::printf("PCM_RESULT {\"app\":\"%s\",\"idle_nonzero\":%zu,\"event_nonzero\":%zu,\"settled_nonzero\":%zu,\"tone_calls\":%u}\n",game::app_id(),idle,event,after,tone_calls);
}
